-- Postgres (Supabase) version of db/init/init.sql: creates the dbo schema, every
-- table, and the demo data. db/init/ stays the SQL Server version (local Docker and
-- the Azure SQL backup); when you change a table there, make the same change here.
--
-- Differences from the SQL Server scripts:
--   * Names are written without quotes, so Postgres stores them in lowercase and
--     matches them in any case (dbo.Users = dbo.users), like SQL Server.
--   * Text comparisons ARE case-sensitive in Postgres ('Dev' <> 'dev').
--   * IDENTITY -> GENERATED BY DEFAULT AS IDENTITY, NVARCHAR -> VARCHAR/TEXT,
--     DATETIME2 -> TIMESTAMP (UTC), BIT -> BOOLEAN, MERGE -> ON CONFLICT DO NOTHING.
--   * Fresh install only: the "upgrade an older database" steps are left out.
--
-- Run with psql from the repo root (see README):
--   psql "<connection string>" -v ON_ERROR_STOP=1 --single-transaction -f db/postgres/init.sql
-- \ir paths are relative to this file. Every statement skips what already exists,
-- so re-running is safe.

CREATE SCHEMA IF NOT EXISTS dbo;

-- TABLES
-- Each dbo table lives in tables/<Table>.sql with its CREATE TABLE and seed data.
-- Order matters: a table comes after the tables it references, and seed data
-- after the rows it depends on.
\ir tables/Departments.sql
\ir tables/Disciplines.sql
\ir tables/Users.sql
\ir tables/Providers.sql
\ir tables/Roles.sql
\ir tables/Drugs.sql
\ir tables/Permissions.sql
\ir tables/RolePermissions.sql
\ir tables/Patients.sql
\ir tables/Staff.sql
\ir tables/T_Login.sql

-- PEOPLE: accounts, people (role, discipline, department), and logins
\ir seed/users.sql

\ir tables/Sessions.sql
\ir tables/PatientDrugs.sql
\ir tables/MedicalHistory.sql
\ir tables/Rooms.sql
\ir tables/FamilyHistory.sql
\ir tables/RoomAssignments.sql
\ir tables/Courses.sql
\ir tables/CourseEnrollments.sql
\ir tables/Cases.sql
\ir tables/Encounters.sql
\ir tables/Assignment.sql
\ir tables/AssignmentGrades.sql
\ir tables/CaseRubric.sql

-- SOAP sprint: encounter identity and chart context. Empty chart tables are intentional:
-- missing data must never be displayed as a normal result or 'no known allergies'.
-- (Encounters.sql runs above, before Assignment.sql, which references it.)
\ir tables/PatientAllergies.sql
\ir tables/PatientVitals.sql
\ir tables/PatientLabResults.sql
\ir tables/ClinicalNotes.sql
\ir tables/Appointments.sql
\ir tables/NoteVersions.sql
\ir tables/NoteAddenda.sql
\ir tables/NoteAuditEvents.sql
\ir tables/BillingCharges.sql
\ir tables/PatientInsurance.sql
\ir tables/DeletionAuditLog.sql

-- DEMO DATA: needs every table above and the logins from seed/users.sql
\ir seed/chart.sql
\ir seed/cases.sql
\ir seed/demo.sql
